const vagon2 = n => {const [t, a] = n.split(':'); return VAG[t](a)};
VAG.automotorM = () => {const L = [], l = 7.4, E = [[-l / 2, 1.42, 3.1, 1.4], [l / 2, 1.42, 3.1, 1.4]]; part(L, casco(E, {e: 3.4}), 'cue'); const tira = (a, b, m, o = .02) => {for (const [p, q] of [[a, b], [Math.PI - b, Math.PI - a]]) part(L, casco(E, {e: 3.4, off: o, a0: p, a1: q, tapas: false}), m)}; tira(.1, .13, TM.brass); tira(.16, .42, 'cre'); tira(.45, .48, TM.brass, .03); for (let k = 0; k < 8; k++) for (const s of [-1, 1]) part(L, PLN(.7, .8), VENT1, (k - 3.5) * .86, 3.5, s * 1.45, 0, s > 0 ? 0 : Math.PI, 0); bajos(L, l - .2, {topes: false}); for (const s of [-1, 1]) part(L, BX(.24, 2.2, 1.5), TM.coal, s * (l / 2 + .06), 2.7, 0); nieveTecho(L, l * .8, .7, 4.48, .16); return {L, len: l + .3, top: 4.7, wheels: ejes(l - .2)}};
